"""Convert integers to their English word representation."""

ONES = [
    "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
    "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
    "seventeen", "eighteen", "nineteen",
]

TENS = [
    "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy",
    "eighty", "ninety",
]

SCALE = [
    (1_000_000_000, "billion"),
    (1_000_000, "million"),
    (1_000, "thousand"),
    (100, "hundred"),
]


def number_to_words(n: int) -> str:
    """Convert an integer to its English word representation.

    Supports range: -999,999,999,999 to 999,999,999,999.
    """
    if not isinstance(n, int):
        raise TypeError(f"Expected int, got {type(n).__name__}")

    if n == 0:
        return "zero"

    if n < 0:
        return "minus " + _convert(-n)

    return _convert(n)


def _convert(n: int) -> str:
    """Convert a positive integer to words."""
    parts = []

    for value, name in SCALE:
        if n >= value:
            count = n // value
            n %= value
            parts.append(_convert_under_1000(count) + " " + name)

    if n > 0:
        parts.append(_convert_under_1000(n))

    return " ".join(parts)


def _convert_under_1000(n: int) -> str:
    """Convert an integer in [1, 999] to words."""
    parts = []

    if n >= 100:
        parts.append(ONES[n // 100] + " hundred")
        n %= 100

    if n >= 20:
        word = TENS[n // 10]
        if n % 10:
            word += "-" + ONES[n % 10]
        parts.append(word)
    elif n > 0:
        parts.append(ONES[n])

    return " ".join(parts)


# ---------- Tests ----------

def test_zero():
    assert number_to_words(0) == "zero"

def test_ones():
    for i in range(1, 10):
        assert number_to_words(i) == ONES[i]

def test_teens():
    for i in range(10, 20):
        assert number_to_words(i) == ONES[i]

def test_tens():
    assert number_to_words(20) == "twenty"
    assert number_to_words(42) == "forty-two"
    assert number_to_words(99) == "ninety-nine"

def test_hundreds():
    assert number_to_words(100) == "one hundred"
    assert number_to_words(123) == "one hundred twenty-three"
    assert number_to_words(999) == "nine hundred ninety-nine"

def test_thousands():
    assert number_to_words(1000) == "one thousand"
    assert number_to_words(12345) == "twelve thousand three hundred forty-five"
    assert number_to_words(999999) == (
        "nine hundred ninety-nine thousand nine hundred ninety-nine"
    )

def test_millions():
    assert number_to_words(1_000_000) == "one million"
    assert number_to_words(1_234_567) == (
        "one million two hundred thirty-four thousand five hundred sixty-seven"
    )

def test_billions():
    assert number_to_words(1_000_000_000) == "one billion"
    assert number_to_words(999_999_999_999) == (
        "nine hundred ninety-nine billion nine hundred ninety-nine million "
        "nine hundred ninety-nine thousand nine hundred ninety-nine"
    )

def test_negative():
    assert number_to_words(-1) == "minus one"
    assert number_to_words(-42) == "minus forty-two"
    assert number_to_words(-1_000_000) == "minus one million"

def test_type_error():
    import pytest
    with pytest.raises(TypeError):
        number_to_words(3.14)


if __name__ == "__main__":
    import pytest
    pytest.main([__file__, "-v"])
